from pathlib import Path
import pandas as pd
P=Path(__file__).resolve().parent
ROOT=P.parents[1]
rows=[]
def add(id,drug,cat,model,endpoint,duration,result,ci,role,limit,url,figure,reg='FDA ingredient/product record; indication/form review required'):
 rows.append(dict(evidence_id=id,compound=drug,CatalogNumber=cat,partner='olaparib' if role!='Alternative cytotoxicity' else 'ongoing olaparib exposure; alternative-drug assessment',model=model,endpoint=endpoint,duration=duration,observed_result=result,reported_combination_index=ci,interpretation_role=role,limitations=limit,source_url=url,source_figure=figure,regulatory_classification=reg,edited_user_model_evidence=False))
add('COMBO001','Selinexor (KPT-330)','B1464','Parental MDA-MB-468, MDA-MB-231 and HCC1937; additional breast lines','Viability, CompuSyn CI','72 h','All15 constant-ratio combinations CI<1; MDA-MB-468 and HCC1937 CI atED50<0.5','MDA-MB-468 ED50 CI<0.5','Empirical exact-line combination candidate','Parental lines; not PARG/TP53BP1/LAMTOR2 or activation models; published graph dose units inconsistent, no graph-derived IC50 invented','https://www.oncotarget.com/article/28047/text/','Fig1C','Current US multiple-myeloma indications; DLBCL indication withdrawn2026-04-30; catalog alias verified by NIH PubChem')
add('COMBO002','Selinexor (KPT-330)','B1464','MDA-MB-468-derived xenografts','Tumour growth and apoptosis','59-day experiment','Authors reported TGI98% combination vs81%olaparib and77%selinexor; tumour growth lower than each monotherapy(p0.0207)','Not quantified by formal CI in vivo','Empirical exact-line combination candidate','Authors describe synergy in vivo; pairwise superiority alone is not a formal interaction test; non-engineered model','https://www.oncotarget.com/article/28047/text/','Fig4','Current US multiple-myeloma indications; DLBCL indication withdrawn2026-04-30')
add('COMBO003','Sirolimus (rapamycin)','A8167','Parental and acquired olaparib-resistant MDA-MB-468; SUM159','MTT viability and normalized isobologram/CI','72 h','Combination inhibited both parental and resistant models; reported strongest MDA468-R CI0.053','MDA468-R as low as0.053; MDA468-P0.129–0.663','Empirical exact-line acquired-resistance combination','Not gene-specific KO/OE; source methods resistant-dose25µM and figure46815µM descriptions differ; no resistance mechanism transfer by assumption','https://pmc.ncbi.nlm.nih.gov/articles/PMC9277186/','Fig6C,D')
add('COMBO004','Everolimus','A8169','Parental and acquired olaparib-resistant SUM159','MTT viability and CI','72 h','Supplement reports synergy','CI<1 qualitatively; exact numbers not transcribed','External-TNBC combination comparator','SuppFig1 is SUM159-P/R; does not establish MDA-MB-468 result for everolimus','https://pmc.ncbi.nlm.nih.gov/articles/PMC9277186/','SupplementaryFig1')
add('COMBO005','Chloroquine','A8628','Parental and acquired olaparib-resistant SUM159','MTT viability and CI','72 h','Supplement reports enhanced olaparib growth inhibition','CI<1 qualitatively; exact numbers not transcribed','External-TNBC combination comparator','SuppFig2 is SUM159-P/R, not468; both inducing/inhibiting autophagy can have context-specific effects','https://pmc.ncbi.nlm.nih.gov/articles/PMC9277186/','SupplementaryFig2')
add('COMBO006','Vorinostat (SAHA)','A4084','Parental MDA-MB-468 and HCC70','MTT viability and Chou-Talalay CI','5 days','No synergistic effect; antagonism in these PTEN-deficient lines','CI>1; exact468 numeric CI not transcribed','Exact-line counterevidence','Sensitive PTEN-expressing MDA-MB-157/231/HCC1143 results do not override468 counterevidence; does not exclude every HDAC drug','https://pmc.ncbi.nlm.nih.gov/articles/PMC4425881/','SupplementaryFigS2;Results;SupplementaryTableS1')
add('COMBO007','Verapamil / elacridar','B1867 / A3384','A2780-derived olaparib-/paclitaxel-resistant ovarian cells','MTT response reversal and calcein/ABCB1 transport assays','MTT72 h; transport15 min','ABCB1 induction correlated with cross-resistance; transport inhibition reversed response','Not a formal CI-derived synergy claim','Mechanism-based efflux reversal','External ovarian acquired-resistance models; verify functionalABCB1 in468OE; single-agent potency is not transport efficacy','https://www.nature.com/articles/bjc2016203','Fig3,4','Verapamil approved ingredient; elacridar investigational control')
add('COMBO008','Cisplatin','A8321','Acquired olaparib-resistant MDA-MB-468 and SUM1315 with parental counterparts','MTT and clonogenic drug sensitivity','MTT72 h; overnightcisplatin pulse then clonogenic growth','Acquired resistant lines retained cisplatin sensitivity comparable to parents','No new resistant-model combination CI transcribed','Alternative cytotoxicity','Resistant468 continuously maintained15µM olaparib; alternative cisplatin susceptibility is not clean proof of restored olaparib sensitivity; GSE165914 exposure/resistance confounded','https://pmc.ncbi.nlm.nih.gov/articles/PMC8339968/','Fig3;Methods')
y=pd.read_csv(ROOT/'analysis/olaparib_screen/L1021_screen_overlap.csv')
for _,r in y[y.author_selected_hit].iterrows():
 reg='Historical US approval; Farydak withdrawn2022-03-24' if r.drug=='Panobinostat' else 'FDA ingredient/product record; indication/form review required'
 result=f'Author-selected screen hit; published monoIC50 {r.mono_ic50_raw}µM, comboIC50 {r.combo_ic50_raw}µM'
