r=y[y.drug.eq('Temozolomide')].iloc[0]
add('YUSOH_TMZ','Temozolomide',r.catalog_number,'Parental MDA-MB-231','MTT author-reported CI','24 h; fixedolaparib10µM','Allthree reported CI values indicate antagonism',f'Atpartner0.1/1/10µM: {r.ci_0_1uM}/{r.ci_1uM}/{r.ci_10uM}','Counterevidence against generic combination','Parental231 does not test PARG-KO collateral vulnerability; TMZ monotherapy and olaparibresensitization are distinct','https://febs.onlinelibrary.wiley.com/doi/10.1002/1878-0261.70093','SupplementTableS2')
d=pd.DataFrame(rows)
# Cisplatin catalog number is retrieved from actual uploaded catalog, not assumed.
lib=pd.read_csv(ROOT/'analysis/drugs_extended/whole_catalog_audit.csv')
ids=lib[lib['Item Name'].str.fullmatch('Cisplatin',case=False,na=False)].CatalogNumber.tolist()
d.loc[d.evidence_id.eq('COMBO008'),'CatalogNumber']='; '.join(ids)
d.to_csv(P/'combo_evidence.csv',index=False)
y[y.author_selected_hit].to_csv(P/'Yusoh_nine_library_hits.csv',index=False)
print('Combination evidence rows',len(d),'Yusoh in-library authorhits',int(y.author_selected_hit.sum()))
